rows.sfo_browse_javascript:
// badges for priority and status (nuBrowseStyleBadge with rules – nuBuilder Next)
nuBrowseStyleBadge(4, {
  Low:    {bg: '#e9ecef', color: '#495057'},
  Normal: {bg: '#cfe2ff', color: '#084298'},
  High:   {bg: '#ffe5d0', color: '#984c0c'},
  Urgent: {bg: '#dc3545', color: '#fff', icon: 'exclamation-triangle'}
});
nuBrowseStyleBadge(5, [
  {equals: 'New', class: 'text-bg-primary'},
  {equals: 'Open', bg: '#cff4fc', color: '#055160'},
  {contains: 'Waiting', bg: '#fff3cd', color: '#664d03', icon: 'hourglass-split'},
  {equals: 'Escalated', class: 'text-bg-danger', icon: 'arrow-up-circle'},
  {equals: 'Resolved', bg: '#d1e7dd', color: '#0f5132', icon: 'check-circle'},
  {default: true, bg: '#e2e3e5', color: '#41464b'}
]);
// overdue: a red Due badge while the ticket is not resolved or closed (test with the row – column 5 = Status, 7 = Due)
nuBrowseStyleBadge(7, [
  {test: function (v, row) {
    var m = v.match(/(\d+)\.(\d+)\.(\d+)\s+(\d+):(\d+)/);
    return !!m && ['Resolved', 'Closed'].indexOf(row[5]) < 0 && new Date(+m[3], m[2] - 1, +m[1], +m[4], +m[5]) < new Date();
  }, bg: '#dc3545', color: '#fff', icon: 'alarm', title: 'overdue'},
  {default: true, badge: false}
]);

rows.sfo_edit_javascript:
// the ticket as the customer sees it: no Handling tab, no internal fields; rating once the ticket is resolved
if (window.tktLevel === 'tkt_customer') {
	nuHideTabByTitle('Handling');
	if (['resolved', 'closed'].indexOf(nuGetValue('tic_status')) < 0) nuHide('tic_rating');
} else if (nuIsNewRecord()) {
	nuHide('tic_rating');
}
// new ticket: sensible defaults (Before Save sets them as well)
if (nuIsNewRecord()) {
	if (!nuGetValue('tic_priority')) nuSetValue('tic_priority', 'normal');
	if (!nuGetValue('tic_status')) nuSetValue('tic_status', 'new');
	if (!nuGetValue('tic_channel')) nuSetValue('tic_channel', window.tktLevel === 'tkt_customer' ? 'portal' : 'phone');
}
// buttons of the Handling tab: only where they make sense
if (nuIsNewRecord() || nuGetValue('tic_agent_id') === window.tktMe) nuHide('tic_take');
if (nuIsNewRecord() || nuGetValue('tic_level') === '2' || !nuUserHasPermission('tkt_escalate')) nuHide('tic_escalate');

rows.sev_javascript:
// take the ticket: assign it to yourself and open it
nuSetValue('tic_agent_id', window.tktMe);
if (nuGetValue('tic_status') === 'new') nuSetValue('tic_status', 'open');
nuSaveAction();

rows.sph_php:
// Before Edit: count the views of customers; customers only open public articles
if ('#ACCESS_LEVEL_CODE#' === 'tkt_customer' && '#RECORD_ID#' !== '-1') {
	if ((string)db_fetch_value('tkt_kb', 'tkt_kb_id', '#RECORD_ID#', 'kb_public') !== '1') nuDisplayError('This article is internal.');
	nuRunQuery('UPDATE tkt_kb SET kb_views = COALESCE(kb_views, 0) + 1 WHERE tkt_kb_id = ?', ['#RECORD_ID#']);
}

// Before Save: defaults, SLA due date, rules – and the old values for After Save
$h = nuHash();
$nudata = $h['nuFORMdata'];
$set = function (string $field, $value) use (&$nudata) { nuSetNuDataValue($nudata, '', $field, $value); };
$level = '#ACCESS_LEVEL_CODE#';
$new = '#RECORD_ID#' === '-1';
$old = $new ? [] : (db_fetch_array(nuRunQuery('SELECT * FROM tkt_ticket WHERE tkt_ticket_id = ?', ['#RECORD_ID#'])) ?: []);
// the value of a field: what the form sends, else the stored one (nuBuilder only sends fields that were edited)
$get = static fn(string $f): string => array_key_exists($f, $h) && !is_array($h[$f]) ? (string)$h[$f] : (string)($old[$f] ?? '');
nuSetProperty('tkt_old_status', (string)($old['tic_status'] ?? ''));
nuSetProperty('tkt_old_agent', (string)($old['tic_agent_id'] ?? ''));
nuSetProperty('tkt_was_new', $new ? '1' : '0');
if ($new) {
	if ($level === 'tkt_customer') { $set('tic_requester_id', '#USER_ID#'); $set('tic_channel', 'portal'); }
	if ($get('tic_status') === '') $set('tic_status', 'new');
	if ($get('tic_priority') === '') $set('tic_priority', 'normal');
	if ($get('tic_level') === '') $set('tic_level', '1');
}
if ($get('tic_requester_id') === '' && $level !== 'tkt_customer') nuDisplayError('Please choose the requester.');
// SLA: due = now + the hours of the category (a quarter for urgent tickets); again when category or priority change
$cat = $get('tic_tkt_category_id');
$prio = $get('tic_priority') ?: 'normal';
$changed = $new || ($old['tic_priority'] ?? '') !== $prio || ($old['tic_tkt_category_id'] ?? '') !== $cat;
if ($cat !== '' && ($changed || $get('tic_due') === '')) {
	$hours = (int)(db_fetch_value('tkt_category', 'tkt_category_id', $cat, 'cat_sla_hours') ?: 24);
	if ($prio === 'urgent') $hours = max(2, intdiv($hours, 4));
	$set('tic_due', date('Y-m-d H:i:s', time() + $hours * 3600));
}
// resolved: time and a resolution text
if (in_array($get('tic_status'), ['resolved', 'closed'], true)) {
	if ($get('tic_resolved_at') === '') $set('tic_resolved_at', date('Y-m-d H:i:s'));
	if (trim($get('tic_resolution')) === '' && $level !== 'tkt_customer') nuDisplayError('Please describe the resolution (tab Handling).');
}
// only team leads give a ticket to someone else (permission item tkt_assign)
$agent = $get('tic_agent_id');
if ($agent !== '' && $agent !== (string)($old['tic_agent_id'] ?? '') && $agent !== '#USER_ID#' && $level !== 'tkt_customer' && !nuUserHasPermission('tkt_assign')) {
	nuDisplayError('Only team leads may assign tickets to someone else (permission item tkt_assign).');
}

// After Save: author of new messages, status after a customer's answer, e-mails and notifications
$id = '#RECORD_ID#';
nuRunQuery("UPDATE tkt_comment SET com_author_id = ?, com_created = ? WHERE com_tkt_ticket_id = ? AND (com_author_id IS NULL OR com_author_id = '')", ['#USER_ID#', date('Y-m-d H:i:s'), $id]);
if ('#ACCESS_LEVEL_CODE#' === 'tkt_customer') nuRunQuery("UPDATE tkt_ticket SET tic_status = 'open' WHERE tkt_ticket_id = ? AND tic_status = 'pending'", [$id]);
$t = db_fetch_object(nuRunQuery('SELECT t.*, r.sus_name AS rname, r.sus_email AS remail, a.sus_name AS aname, a.sus_email AS aemail FROM tkt_ticket t
	LEFT JOIN zzzzsys_user r ON r.zzzzsys_user_id = t.tic_requester_id LEFT JOIN zzzzsys_user a ON a.zzzzsys_user_id = t.tic_agent_id WHERE t.tkt_ticket_id = ?', [$id]));
if (!$t) return;
$due = $t->tic_due ? date('d.m.Y H:i', strtotime($t->tic_due)) : '–';
// e-mail templates (group tkt): [placeholders] are filled here, #hash variables# by nuSendEmailFromTemplate – without e-mail settings nothing is sent
$mail = function (string $code, ?string $to, array $fill) {
	$tpl = nuGetEmailTemplateData($code, '', 'tkt');
	if (!$tpl || !$to) return;
	$tpl['to'] = $to;
	foreach ($fill as $k => $v) $tpl['body'] = str_replace('[' . $k . ']', htmlspecialchars((string)$v), (string)$tpl['body']);
	try { nuSendEmailFromTemplate($tpl); } catch (Throwable $e) { nuDebug('tkt mail: ' . $e->getMessage()); }
};
if (nuGetProperty('tkt_was_new') === '1') $mail('tkt_mail_created', $t->remail, ['requester' => $t->rname, 'due' => $due]);
if ($t->tic_agent_id && $t->tic_agent_id !== nuGetProperty('tkt_old_agent') && $t->tic_agent_id !== '#USER_ID#') {
	$mail('tkt_mail_assigned', $t->aemail, ['agent' => $t->aname, 'due' => $due]);
	nuNextNotify(['title' => 'Assigned to you: #' . $t->tic_number . ' ' . $t->tic_subject, 'body' => 'From #USER_FIRST_NAME# #USER_LAST_NAME# · due ' . $due, 'users' => [$t->tic_agent_id], 'level' => 'info']);
}
if ($t->tic_status === 'resolved' && nuGetProperty('tkt_old_status') !== 'resolved') $mail('tkt_mail_resolved', $t->remail, ['requester' => $t->rname, 'resolution' => $t->tic_resolution]);

// Before Edit: who is looking at the ticket
$level = '#ACCESS_LEVEL_CODE#';
// customers only open their own tickets – also when they type another record id into the address
if ($level === 'tkt_customer' && '#RECORD_ID#' !== '-1') {
	$owner = db_fetch_value('tkt_ticket', 'tkt_ticket_id', '#RECORD_ID#', 'tic_requester_id');
	if ($owner !== '#USER_ID#') nuDisplayError('This ticket belongs to another customer.');
}
// values for the form's JavaScript (Take ticket, the customer view)
nuAddJavascript('window.tktMe = ' . json_encode('#USER_ID#') . '; window.tktLevel = ' . json_encode($level) . ';');

// Run from the button "Escalate" of a ticket (hidden procedure: no window, JavaScript back to the form)
if (!nuUserHasPermission('tkt_escalate')) { nuDisplayError('You may not escalate tickets (permission item tkt_escalate).'); return; }
$id = '#RECORD_ID#';
if ($id === '' || $id === '-1') { nuDisplayError('Save the ticket first.'); return; }
nuRunQuery("UPDATE tkt_ticket SET tic_level = 2, tic_status = 'escalated', tic_agent_id = NULL WHERE tkt_ticket_id = ?", [$id]);
nuRunQuery('INSERT INTO tkt_comment (tkt_comment_id, com_tkt_ticket_id, com_author_id, com_created, com_body, com_internal) VALUES (?, ?, ?, ?, ?, 1)',
	[nuID(), $id, '#USER_ID#', date('Y-m-d H:i:s'), 'Escalated to the 2nd level by #USER_FIRST_NAME#.']);
// in-app notification for every specialist (bell at the top)
$t = db_fetch_object(nuRunQuery('SELECT tic_number, tic_subject FROM tkt_ticket WHERE tkt_ticket_id = ?', [$id]));
if (function_exists('nuNextNotify')) nuNextNotify(['title' => 'Escalated: #' . ($t->tic_number ?? '') . ' ' . ($t->tic_subject ?? ''),
	'body' => 'Escalated by #USER_FIRST_NAME# #USER_LAST_NAME#.', 'access_levels' => ['tkt_specialist'], 'level' => 'warning']);
nuAddJavascript("nuMessage(['Ticket escalated', 'The specialists were notified.']); setTimeout(function () { nuGetBreadcrumb(); }, 1200);");

// Team lead's button on the start page: resolved tickets without an answer of the customer for 7 days are closed
$s = nuRunQuery("SELECT COUNT(*) FROM tkt_ticket WHERE tic_status = 'resolved' AND tic_resolved_at < ?", [date('Y-m-d H:i:s', strtotime('-7 days'))]);
$n = (int)(db_fetch_row($s)[0] ?? 0);
nuRunQuery("UPDATE tkt_ticket SET tic_status = 'closed' WHERE tic_status = 'resolved' AND tic_resolved_at < ?", [date('Y-m-d H:i:s', strtotime('-7 days'))]);
nuAddJavascript("nuMessage(['Housekeeping', '" . $n . " resolved tickets were closed.']); if (window.nuNextDashboardRefresh) nuNextDashboardRefresh();");
